fig.text(.5,.003,'Gray band = local-tree coverage (5.0–37.055 Mb); orange shading = published inversion intervals. Nucleotide scans span the full chr17 contig; tracks are not interpolated.',ha='center',fontsize=8)
for ext in ('png','pdf','svg'):fig.savefig(G/f'house_mouse_chr17_final_v1.{ext}',dpi=300 if ext=='png' else None,bbox_inches='tight')
plt.close(fig)
print('created',len(rows),'final result rows',len(sp),'spatial rows; missing robustness chunks',missing)
